# =============================================================================
# 01_scrape_admissions_2026.R           (formerly admission_26.R, Sept 2026)
# -----------------------------------------------------------------------------
# Turns Manchester City Council's "demand for primary school places" pages
# (Reception, September 2026 intake) into one tidy table:
#
#   school_name      - school name as the council writes it
#   places           - published admission number (Reception places)
#   offers           - offers made; "*" = includes alternative offers,
#                      "^" = includes late applications
#   unfilled_places  - places left after offers
#   criteria         - how far down the admissions criteria offers went, e.g.
#                      "All on-time applicants offered" or "... to a distance
#                      of 0.449 miles" (the effective catchment radius)
#
# The council website blocks scripted requests, so the page HTML was copied by
# hand (browser > Inspect > copy the <article> element) and pasted into the
# raw strings below. Long pages are split across several strings.
#
# Output: data/manchester_primary_school_places.csv  (used by 05_shortlist_2025.R)
# =============================================================================

library(rvest)
library(dplyr)
library(purrr)
library(stringr)

# The council uses two wordings for the same fields depending on the page:
#   "Places:" / "Offers:"   and   "Total places available:" / "Offers made:"
PLACES_RE   <- "^(Total places available|Places):"
OFFERS_RE   <- "^(Offers made|Offers):"
UNFILLED_RE <- "^Unfilled places:"

#' Parse one chunk of pasted HTML into a data frame (one row per school).
#'
#' Each school is a <p><strong>Name</strong></p> followed by a <ul> whose
#' first <li> gives the number of places. Matching on that pattern rather
#' than on surrounding <div>s makes it robust to layout differences between
#' the A-C, D-P, R-S and T-W pages.
#'
#' @param html character. Raw HTML pasted from the page.
#' @return tibble: school_name, places, offers, unfilled_places, criteria
parse_school_places <- function(html) {

  page <- read_html(html)

  school_lists <- page %>%
    html_elements(xpath = paste0(
      '//ul[li[1][starts-with(normalize-space(text()), "Places:") or ',
      'starts-with(normalize-space(text()), "Total places available:")]]'))

  if (length(school_lists) == 0) {
    warning("No school entries found in this HTML.")
    return(tibble(school_name = character(), places = integer(),
                  offers = character(), unfilled_places = integer(),
                  criteria = character()))
  }

  map_dfr(school_lists, function(ul) {
    # School name = nearest preceding <p> sibling
    name_node   <- ul %>% html_elements(xpath = "preceding-sibling::p[1]")
    school_name <- if (length(name_node) > 0) html_text2(name_node[[1]]) else NA_character_

    items        <- ul %>% html_elements("li") %>% html_text2()
    places_txt   <- items[str_detect(items, PLACES_RE)]
    offers_txt   <- items[str_detect(items, OFFERS_RE)]
    unfilled_txt <- items[str_detect(items, UNFILLED_RE)]
    # Whatever is left describes the offer criteria
    criteria_txt <- items[!items %in% c(places_txt, offers_txt, unfilled_txt)]

    tibble(
      school_name     = school_name,
      places          = as.integer(str_extract(places_txt, "\\d+")),
      offers          = str_trim(str_remove(offers_txt, OFFERS_RE)),
      unfilled_places = as.integer(str_extract(unfilled_txt, "\\d+")),
      criteria        = paste(criteria_txt, collapse = " ")
    )
  })
}

